package tools_test

import (
	"context"
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/tylinux/nex/go/internal/adapters/fsx"
	tools2 "github.com/tylinux/nex/go/internal/tools"
)

// The vectors are generated by scripts/go-rewrite/gen-tool-vectors.mts against the
// real TypeScript handlers; these tests replay the same fixture tree and require
// byte-identical model content, output fields and resulting tree.

const wsPlaceholder = "<WS>"

type fixtureFile struct {
	Path    string  `json:"path"`
	Content *string `json:"content"`
	Bytes   []int   `json:"bytes"`
	Mode    *uint32 `json:"mode"`
}

type preRead struct {
	Path  string         `json:"path"`
	Input map[string]any `json:"input"`
}

type treeEntry struct {
	Content     *string `json:"content"`
	BytesBase64 string  `json:"bytesBase64"`
	SizeBytes   int64   `json:"sizeBytes"`
	Mode        string  `json:"mode"`
}

type caseResult struct {
	ModelContent   json.RawMessage      `json:"modelContent"`
	Output         json.RawMessage      `json:"output"`
	Failed         bool                 `json:"failed"`
	FailureMessage *string              `json:"failureMessage"`
	ErrorName      *string              `json:"errorName"`
	ErrorMessage   *string              `json:"errorMessage"`
	TreeAfter      map[string]treeEntry `json:"treeAfter"`
}

type toolCase struct {
	Name               string        `json:"name"`
	Files              []fixtureFile `json:"files"`
	PreRead            []preRead     `json:"preRead"`
	BumpMtime          bool          `json:"bumpMtime"`
	MutateAfterPreRead *struct {
		Path    string `json:"path"`
		Content string `json:"content"`
	} `json:"mutateAfterPreRead"`
	Input  map[string]any `json:"input"`
	Result caseResult     `json:"result"`
}

type toolVectors struct {
	Tool  string     `json:"tool"`
	Cases []toolCase `json:"cases"`
}

func loadVectors(t *testing.T, name string) toolVectors {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("..", "..", "testdata", "vectors", name))
	if err != nil {
		t.Fatalf("read %s: %v", name, err)
	}
	var v toolVectors
	if err := json.Unmarshal(raw, &v); err != nil {
		t.Fatalf("parse %s: %v", name, err)
	}
	return v
}

func writeFixtures(t *testing.T, root string, files []fixtureFile) {
	t.Helper()
	for _, f := range files {
		abs := filepath.Join(root, filepath.FromSlash(f.Path))
		if err := os.MkdirAll(filepath.Dir(abs), 0o777); err != nil {
			t.Fatal(err)
		}
		var data []byte
		if f.Bytes != nil {
			data = make([]byte, len(f.Bytes))
			for i, b := range f.Bytes {
				data[i] = byte(b)
			}
		} else if f.Content != nil {
			data = []byte(*f.Content)
		}
		if err := os.WriteFile(abs, data, 0o666); err != nil {
			t.Fatal(err)
		}
		if f.Mode != nil {
			if err := os.Chmod(abs, os.FileMode(*f.Mode)); err != nil {
				t.Fatal(err)
			}
		}
	}
}

func snapshotTree(t *testing.T, root string) map[string]treeEntry {
	t.Helper()
	out := map[string]treeEntry{}
	err := filepath.WalkDir(root, func(p string, d os.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, _ := filepath.Rel(root, p)
		rel = filepath.ToSlash(rel)
		info, err := d.Info()
		if err != nil {
			return err
		}
		data, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		text := string(data)
		out[rel] = treeEntry{
			Content:     &text,
			BytesBase64: base64.StdEncoding.EncodeToString(data),
			SizeBytes:   info.Size(),
			Mode:        fmt.Sprintf("%o", info.Mode().Perm()),
		}
		return nil
	})
	if err != nil {
		t.Fatal(err)
	}
	return out
}

// runCase replays one vector case and returns the Go model content, marshalled
// output and the JSON error message (if failed).
func runCase(t *testing.T, toolName string, c toolCase, fxp tools2.FS, root string) (model string, outJSON []byte, failure *tools2.Failure, other error) {
	state := tools2.NewReadState()
	// directory mtimes: preRead runs the real tools2.Read to seed the state.
	for _, pr := range c.PreRead {
		input := map[string]any{}
		for k, v := range pr.Input {
			input[k] = v
		}
		input["file_path"] = filepath.Join(root, filepath.FromSlash(pr.Path))
		readCtx := &tools2.Context{FS: fxp, ReadState: state, WorkingDirectory: root, WorkspaceRoot: root, SessionID: "sess_test", Ctx: context.Background()}
		if _, err := tools2.Read(input, readCtx); err != nil {
			t.Fatalf("%s: preRead %s: %v", c.Name, pr.Path, err)
		}
	}
	if c.MutateAfterPreRead != nil {
		if err := os.WriteFile(filepath.Join(root, filepath.FromSlash(c.MutateAfterPreRead.Path)), []byte(c.MutateAfterPreRead.Content), 0o666); err != nil {
			t.Fatal(err)
		}
	}
	// Same order as the generator: mutate first, then bump. Writing resets mtime to
	// "now", so bumping before the write leaves the mtime advance up to wall-clock
	// millisecond rounding and the case stops being reproducible.
	if c.BumpMtime {
		for _, pr := range c.PreRead {
			abs := filepath.Join(root, filepath.FromSlash(pr.Path))
			bumpMtime(t, abs)
		}
	}

	ctx := &tools2.Context{FS: fxp, ReadState: state, WorkingDirectory: root, WorkspaceRoot: root, SessionID: "sess_test", Ctx: context.Background()}
	input := map[string]any{}
	for k, v := range c.Input {
		input[k] = v
	}
	if fp, ok := input["file_path"].(string); ok && fp != "" && !filepath.IsAbs(fp) {
		input["file_path"] = filepath.Join(root, filepath.FromSlash(fp))
	}

	switch toolName {
	case "read":
		o, err := tools2.Read(input, ctx)
		if err != nil {
			return "", nil, asFailure(err), err
		}
		b, _ := json.Marshal(o)
		return tools2.FormatReadModelContent(o), b, nil, nil
	case "write":
		o, err := tools2.Write(input, ctx)
		if err != nil {
			return "", nil, asFailure(err), err
		}
		b, _ := json.Marshal(o)
		return tools2.FormatWriteModelContent(o), b, nil, nil
	case "edit":
		o, err := tools2.Edit(input, ctx)
		if err != nil {
			return "", nil, asFailure(err), err
		}
		b, _ := json.Marshal(o)
		return tools2.FormatEditModelContent(o), b, nil, nil
	}
	t.Fatalf("unknown tool %s", toolName)
	return "", nil, nil, nil
}

func asFailure(err error) *tools2.Failure {
	if f, ok := err.(*tools2.Failure); ok {
		return f
	}
	return nil
}

// TestReadVectors / TestWriteVectors / TestEditVectors replay the generated cases.
func TestReadVectors(t *testing.T)  { replayVectors(t, "read", "tools-read.json") }
func TestWriteVectors(t *testing.T) { replayVectors(t, "write", "tools-write.json") }
func TestEditVectors(t *testing.T)  { replayVectors(t, "edit", "tools-edit.json") }

// minDifferentialCases is the plan's floor for the differential vectors of each tool
// (phase-1-go-agent.md step 1.8: "Minimum 30 inputs each for Read, Edit, Write").
// It counts *asserting* cases: raw ZodError inputs are rejected by the JSON-schema
// stage before the handler runs and are covered by tools-validation.json instead.
const minDifferentialCases = 30

// assertsHandlerBehaviour reports whether a case compares Go against a real
// TypeScript handler outcome (result text, output JSON) rather than only replaying
// the fixture tree.
func assertsHandlerBehaviour(c toolCase) bool {
	if !c.Result.Failed {
		return true
	}
	want := deref(c.Result.FailureMessage)
	if want == "" {
		want = deref(c.Result.ErrorMessage)
	}
	return !strings.HasPrefix(want, "[") && !strings.HasPrefix(want, "{")
}

func replayVectors(t *testing.T, toolName, file string) {
	t.Helper()
	v := loadVectors(t, file)
	asserting := 0
	for _, c := range v.Cases {
		if assertsHandlerBehaviour(c) {
			asserting++
		}
	}
	if asserting < minDifferentialCases {
		t.Fatalf("%s: only %d of %d cases assert handler behaviour, want >= %d",
			file, asserting, len(v.Cases), minDifferentialCases)
	}
	fxp := fsx.NewPort()
	for _, c := range v.Cases {
		c := c
		t.Run(c.Name, func(t *testing.T) {
			root := t.TempDir()
			writeFixtures(t, root, c.Files)
			model, outJSON, failure, otherErr := runCase(t, toolName, c, fxp, root)

			if c.Result.Failed {
				wantRaw := deref(c.Result.FailureMessage)
				if wantRaw == "" {
					wantRaw = deref(c.Result.ErrorMessage)
				}
				if !assertsHandlerBehaviour(c) {
					// Raw ZodError: in the real executor these inputs are rejected
					// by the JSON-schema stage before the handler runs, so the
					// model-visible text is covered by tools-validation.json.
					t.Skipf("handler-level raw schema error, covered by validation vectors: %s", wantRaw)
				}
				if failure == nil && otherErr == nil {
					t.Fatalf("expected failure %q, got success model=%q", wantRaw, model)
				}
				got := ""
				if failure != nil {
					got = failure.Message
				} else {
					got = otherErr.Error()
				}
				want := replaceWS(wantRaw, root)
				if got != want {
					t.Fatalf("failure message mismatch\n got: %q\nwant: %q", got, want)
				}
			} else {
				if failure != nil {
					t.Fatalf("unexpected failure: %q", failure.Message)
				}
				if otherErr != nil {
					t.Fatalf("unexpected error: %v", otherErr)
				}
				var wantModel string
				if err := json.Unmarshal(c.Result.ModelContent, &wantModel); err != nil {
					t.Fatalf("model content not a string: %v", err)
				}
				wantModel = replaceWS(wantModel, root)
				if model != wantModel {
					t.Fatalf("model content mismatch\n got: %q\nwant: %q", model, wantModel)
				}
				compareOutput(t, c.Result.Output, outJSON, root)
			}

			compareTree(t, c.Result.TreeAfter, snapshotTree(t, root), root)
		})
	}
}

func compareOutput(t *testing.T, wantRaw, gotRaw json.RawMessage, root string) {
	t.Helper()
	var want, got map[string]any
	if err := json.Unmarshal(wantRaw, &want); err != nil {
		t.Fatalf("want output: %v", err)
	}
	if err := json.Unmarshal(gotRaw, &got); err != nil {
		t.Fatalf("got output: %v", err)
	}
	want = normalizeTree(want, root).(map[string]any)
	// The Go output intentionally omits fields the port does not model (perf,
	// structuredPatch internals are kept); compare only keys present in the
	// TypeScript output that Go also models, plus require no extra keys.
	for k, wv := range want {
		gv, ok := got[k]
		if !ok {
			t.Fatalf("output missing key %q (want %v)", k, wv)
		}
		if !jsonEqual(wv, gv) {
			t.Fatalf("output[%q] mismatch\n got: %#v\nwant: %#v", k, gv, wv)
		}
	}
	for k := range got {
		if _, ok := want[k]; !ok {
			t.Fatalf("output has unexpected key %q", k)
		}
	}
}

func compareTree(t *testing.T, want map[string]treeEntry, got map[string]treeEntry, root string) {
	t.Helper()
	if len(want) != len(got) {
		t.Fatalf("tree size mismatch: got %d files, want %d\n got: %v\nwant: %v", len(got), len(want), keys(got), keys(want))
	}
	for k, wv := range want {
		gv, ok := got[k]
		if !ok {
			t.Fatalf("tree missing %q", k)
		}
		if wv.BytesBase64 != gv.BytesBase64 {
			t.Fatalf("tree[%q] bytes mismatch\n got: %q\nwant: %q", k, deref(gv.Content), deref(wv.Content))
		}
		if wv.Mode != gv.Mode {
			t.Fatalf("tree[%q] mode mismatch: got %s want %s", k, gv.Mode, wv.Mode)
		}
	}
}

func keys(m map[string]treeEntry) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}

func deref(s *string) string {
	if s == nil {
		return ""
	}
	return *s
}

func jsonEqual(a, b any) bool {
	ab, _ := json.Marshal(a)
	bb, _ := json.Marshal(b)
	return string(ab) == string(bb)
}

func replaceWS(s, root string) string { return strings.ReplaceAll(s, wsPlaceholder, root) }

// normalizeTree replaces the <WS> placeholder in every string with the real root.
func normalizeTree(v any, root string) any {
	switch x := v.(type) {
	case string:
		return replaceWS(x, root)
	case []any:
		for i := range x {
			x[i] = normalizeTree(x[i], root)
		}
		return x
	case map[string]any:
		for k := range x {
			x[k] = normalizeTree(x[k], root)
		}
		return x
	default:
		return v
	}
}

func bumpMtime(t *testing.T, path string) {
	t.Helper()
	info, err := os.Stat(path)
	if err != nil {
		t.Fatal(err)
	}
	future := info.ModTime().Add(5 * time.Second)
	if err := os.Chtimes(path, future, future); err != nil {
		t.Fatal(err)
	}
}
